**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("siatka.txt");
    int tab[7][7];
    for (int i = 0; i < 7; i++)
        for (int j = 0; j < 7; j++)
            plik >> tab[i][j];

    int bestK = 0, bestI = 0, bestJ = 0;

    for (int i = 0; i < 7; i++) {
        for (int j = 0; j < 7; j++) {
            if (tab[i][j] == 0) continue;
            // Sprawdz maksymalny kwadrat z lewym gornym rogiem (i,j)
            int maxK = min(7 - i, 7 - j); // nie wyjsc poza siatke
            for (int k = 1; k <= maxK; k++) {
                bool ok = true;
                // Sprawdz nowy wiersz i nowa kolumne dodawane przez powiekszenie
                for (int jj = j; jj < j + k && ok; jj++)
                    if (tab[i + k - 1][jj] == 0) ok = false;
                for (int ii = i; ii < i + k - 1 && ok; ii++)
                    if (tab[ii][j + k - 1] == 0) ok = false;
                if (!ok) break;
                if (k > bestK) {
                    bestK = k;
                    bestI = i;
                    bestJ = j;
                }
            }
        }
    }

    cout << "a) Najwiekszy kwadrat jedynek: " << bestK << endl;
    cout << "b) Lewy gorny rog: (" << bestI + 1 << ", " << bestJ + 1 << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdej pozycji (i,j) probujemy powiekszyc kwadrat. Sprawdzamy kolejne rozmiary — nowy wiersz dolny i nowa kolumna prawa musza byc jedynkami. Jesli natrafimy na zero, konczymy.

